#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sum_basic() {
        assert_eq!(parallel_sum((1..=100).collect(), 4), 5050);
        assert_eq!(parallel_sum((1..=100).collect(), 3), 5050);
    }

    #[test]
    fn sum_edge_cases() {
        assert_eq!(parallel_sum(vec![], 4), 0);
        assert_eq!(parallel_sum(vec![7, 8], 16), 15);
        assert_eq!(parallel_sum(vec![1, 2, 3], 0), 6);
    }

    #[test]
    fn sum_large() {
        let v: Vec<u64> = (0..1_000_000).collect();
        assert_eq!(parallel_sum(v, 8), 499_999_500_000);
    }

    #[test]
    fn counter() {
        assert_eq!(concurrent_count(8, 1000), 8000);
        assert_eq!(concurrent_count(1, 5), 5);
        assert_eq!(concurrent_count(0, 100), 0);
        assert_eq!(concurrent_count(4, 0), 0);
    }
}
